package br.com.puraresenha.puraarena;
import org.bukkit.*;import org.bukkit.attribute.Attribute;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.entity.PlayerDeathEvent;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.scheduler.BukkitTask;import java.io.*;import java.util.*;
public final class PuraArenaPlugin extends JavaPlugin implements Listener,CommandExecutor,TabCompleter{
 private final Map<UUID,State> saved=new HashMap<>();private final Map<UUID,UUID> fights=new HashMap<>(),invites=new HashMap<>();private final Set<UUID> queue=new LinkedHashSet<>();private final Map<UUID,BukkitTask> timers=new HashMap<>();private final Map<UUID,String> kits=new HashMap<>();private final Map<UUID,Integer>wins=new HashMap<>();private Location p1,p2;
 public void onEnable(){saveDefaultConfig();loadArena();getServer().getPluginManager().registerEvents(this,this);for(String c:List.of("gladiador","x1","arena")){getCommand(c).setExecutor(this);getCommand(c).setTabCompleter(this);}recover();getLogger().info("PuraArena ativada.");}
 private void loadArena(){World w=Bukkit.getWorld(getConfig().getString("arena.world","world"));if(w==null)return;p1=loc(w,"arena.pos1");p2=loc(w,"arena.pos2");}
 private Location loc(World w,String s){return new Location(w,getConfig().getDouble(s+".x"),getConfig().getDouble(s+".y"),getConfig().getDouble(s+".z"),(float)getConfig().getDouble(s+".yaw"),(float)getConfig().getDouble(s+".pitch"));}
 private boolean ready(){return p1!=null&&p2!=null;}
 public boolean onCommand(CommandSender sender,Command cmd,String label,String[] a){if(!(sender instanceof Player p)){sender.sendMessage("Apenas jogadores.");return true;}String c=cmd.getName();
 if(c.equals("gladiador")){if(a.length==0){menu(p);return true;}if(a[0].equalsIgnoreCase("entrar")){join(p);return true;}if(a[0].equalsIgnoreCase("sair")){queue.remove(p.getUniqueId());p.sendMessage("§7Voce saiu da fila.");return true;}p.sendMessage("/gladiador [entrar|sair]");return true;}
 if(c.equals("x1")){if(a.length==0){p.sendMessage("/x1 jogador|aceitar|recusar|cancelar");return true;}switch(a[0].toLowerCase()){case "aceitar"->accept(p);case "recusar"->decline(p);case "cancelar"->cancel(p);default->{Player t=Bukkit.getPlayerExact(a[0]);if(t==null||t.equals(p)){p.sendMessage("§cJogador invalido.");return true;}invite(p,t);}}return true;}
 if(a.length>0&&a[0].equalsIgnoreCase("top")){p.sendMessage("§6PuraArena §7| Vitorias: §a"+wins.getOrDefault(p.getUniqueId(),0));}else p.sendMessage("/arena top");return true;}
 private ItemStack item(Material m,String n,String l){ItemStack i=new ItemStack(m);ItemMeta x=i.getItemMeta();x.setDisplayName(n);x.setLore(List.of(l));i.setItemMeta(x);return i;}
 private void menu(Player p){Inventory i=Bukkit.createInventory(null,27,"§8PuraArena");i.setItem(10,item(Material.IRON_SWORD,"§aGladiador livre","§7Entrar na fila"));i.setItem(13,item(Material.NETHERITE_CHESTPLATE,"§eKits","§7Atual: "+kits.getOrDefault(p.getUniqueId(),"Classico")));i.setItem(16,item(Material.DIAMOND_SWORD,"§bX1 particular","§7Use /x1 jogador"));i.setItem(22,item(Material.BARRIER,"§cSair da fila","§7"));p.openInventory(i);}
 @EventHandler public void menuClick(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;String title=e.getView().getTitle();if(!title.equals("§8PuraArena")&&!title.equals("§8Kits PuraArena"))return;e.setCancelled(true);if(e.getCurrentItem()==null)return;int slot=e.getRawSlot();if(title.equals("§8PuraArena")){if(slot==10){p.closeInventory();join(p);}if(slot==13){Inventory k=Bukkit.createInventory(null,27,"§8Kits PuraArena");k.setItem(10,item(Material.IRON_SWORD,"§fClassico","§7"));k.setItem(12,item(Material.MACE,"§6Mace","§7"));k.setItem(14,item(Material.BOW,"§aArqueiro","§7"));Material spear=Material.matchMaterial("SPEAR");k.setItem(16,item(spear==null?Material.TRIDENT:spear,"§bLanca","§7"));p.openInventory(k);}if(slot==16){p.closeInventory();p.sendMessage("§eUse /x1 jogador.");}if(slot==22){queue.remove(p.getUniqueId());p.closeInventory();p.sendMessage("§7Fila cancelada.");}}else{String kit=switch(slot){case 10->"Classico";case 12->"Mace";case 14->"Arqueiro";case 16->"Lanca";default->null;};if(kit!=null){kits.put(p.getUniqueId(),kit);p.closeInventory();p.sendMessage("§aKit escolhido: "+kit);}}}
 private void join(Player p){if(!ready()){p.sendMessage("§cConfigure arena.world, arena.pos1 e arena.pos2 no config.yml.");return;}if(saved.containsKey(p.getUniqueId())){p.sendMessage("§cVoce ja esta em partida.");return;}queue.add(p.getUniqueId());p.sendMessage("§aVoce entrou na fila.");Iterator<UUID> it=queue.iterator();if(!it.hasNext())return;UUID a=it.next();if(!it.hasNext())return;UUID b=it.next();queue.remove(a);queue.remove(b);Player x=Bukkit.getPlayer(a),y=Bukkit.getPlayer(b);if(x!=null&&y!=null)start(x,y);}
 private void invite(Player a,Player b){if(!ready()||saved.containsKey(a.getUniqueId())||saved.containsKey(b.getUniqueId())||invites.containsKey(b.getUniqueId())){a.sendMessage("§cNao foi possivel enviar o convite.");return;}invites.put(b.getUniqueId(),a.getUniqueId());a.sendMessage("§aConvite enviado. Expira em 60 segundos.");b.sendMessage("§e"+a.getName()+" te chamou para X1. /x1 aceitar ou /x1 recusar (60s).");timers.put(b.getUniqueId(),Bukkit.getScheduler().runTaskLater(this,()->{UUID from=invites.remove(b.getUniqueId());timers.remove(b.getUniqueId());if(from!=null){Player x=Bukkit.getPlayer(from);if(x!=null)x.sendMessage("§cConvite expirou.");if(b.isOnline())b.sendMessage("§cConvite expirado.");}},1200L));}
 private void accept(Player p){UUID id=invites.remove(p.getUniqueId());timer(p);if(id==null){p.sendMessage("§cSem convite pendente.");return;}Player a=Bukkit.getPlayer(id);if(a==null){p.sendMessage("§cDesafiante offline.");return;}start(a,p);}
 private void decline(Player p){UUID id=invites.remove(p.getUniqueId());timer(p);if(id==null){p.sendMessage("§cSem convite.");return;}Player a=Bukkit.getPlayer(id);if(a!=null)a.sendMessage("§c"+p.getName()+" recusou.");p.sendMessage("§7Convite recusado.");}
 private void cancel(Player p){UUID target=null;for(var e:invites.entrySet())if(e.getValue().equals(p.getUniqueId())){target=e.getKey();break;}if(target==null){p.sendMessage("§cNenhum convite enviado.");return;}invites.remove(target);timer(Bukkit.getPlayer(target));Player t=Bukkit.getPlayer(target);if(t!=null)t.sendMessage("§cConvite cancelado pelo desafiante.");p.sendMessage("§aConvite cancelado.");}
 private void timer(Player p){if(p==null)return;BukkitTask t=timers.remove(p.getUniqueId());if(t!=null)t.cancel();}
 private void start(Player a,Player b){if(!ready()||saved.containsKey(a.getUniqueId())||saved.containsKey(b.getUniqueId()))return;queue.remove(a.getUniqueId());queue.remove(b.getUniqueId());saved.put(a.getUniqueId(),State.take(a));saved.put(b.getUniqueId(),State.take(b));persist();fights.put(a.getUniqueId(),b.getUniqueId());fights.put(b.getUniqueId(),a.getUniqueId());prepare(a,p1);prepare(b,p2);give(a,kits.getOrDefault(a.getUniqueId(),"Classico"));give(b,kits.getOrDefault(b.getUniqueId(),"Classico"));a.sendMessage("§6PURA ARENA §7X1 contra §e"+b.getName());b.sendMessage("§6PURA ARENA §7X1 contra §e"+a.getName());}
 private void prepare(Player p,Location l){p.closeInventory();p.getInventory().clear();p.getInventory().setArmorContents(new ItemStack[4]);p.getInventory().setItemInOffHand(null);p.setExp(0);p.setLevel(0);p.setFireTicks(0);p.setHealth(p.getAttribute(Attribute.MAX_HEALTH).getValue());p.setFoodLevel(20);p.setSaturation(20);p.setGameMode(GameMode.SURVIVAL);p.teleport(l);}
 private void armor(PlayerInventory i,Material m){String s=m.name();i.setHelmet(new ItemStack(Material.valueOf(s+"_HELMET")));i.setChestplate(new ItemStack(Material.valueOf(s+"_CHESTPLATE")));i.setLeggings(new ItemStack(Material.valueOf(s+"_LEGGINGS")));i.setBoots(new ItemStack(Material.valueOf(s+"_BOOTS")));}
 private void give(Player p,String k){PlayerInventory i=p.getInventory();switch(k){case "Mace"->{i.addItem(new ItemStack(Material.MACE));i.addItem(new ItemStack(Material.GOLDEN_APPLE,4));armor(i,Material.DIAMOND);}case "Arqueiro"->{i.addItem(new ItemStack(Material.IRON_SWORD));i.addItem(new ItemStack(Material.BOW));i.addItem(new ItemStack(Material.ARROW,32));armor(i,Material.IRON);}case "Lanca"->{Material m=Material.matchMaterial("SPEAR");i.addItem(new ItemStack(m==null?Material.TRIDENT:m));i.addItem(new ItemStack(Material.IRON_SWORD));armor(i,Material.DIAMOND);}default->{i.addItem(new ItemStack(Material.IRON_SWORD));i.addItem(new ItemStack(Material.SHIELD));i.addItem(new ItemStack(Material.GOLDEN_APPLE,4));armor(i,Material.IRON);}}}
 @EventHandler public void death(PlayerDeathEvent e){Player loser=e.getEntity();UUID id=loser.getUniqueId(),other=fights.get(id);if(other==null)return;e.getDrops().clear();e.setDroppedExp(0);Player winner=Bukkit.getPlayer(other);if(winner!=null){wins.merge(other,1,Integer::sum);winner.sendMessage("§aVoce venceu contra "+loser.getName()+"!");}loser.sendMessage("§cVoce perdeu. Inventario original sera restaurado.");Bukkit.getScheduler().runTask(this,()->{loser.spigot().respawn();Bukkit.getScheduler().runTaskLater(this,()->{restore(loser);if(winner!=null)restore(winner);fights.remove(id);fights.remove(other);},2L);});}
 private void restore(Player p){State s=saved.remove(p.getUniqueId());if(s!=null)s.putBack(p);persist();}
 @EventHandler public void quit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId(),other=fights.get(id);queue.remove(id);if(other!=null){Player p=Bukkit.getPlayer(other);if(p!=null){p.sendMessage("§aVitoria por W.O.");wins.merge(other,1,Integer::sum);restore(p);}fights.remove(id);fights.remove(other);}}
 @EventHandler public void join(PlayerJoinEvent e){Bukkit.getScheduler().runTaskLater(this,()->restore(e.getPlayer()),1L);}
 @EventHandler public void drop(PlayerDropItemEvent e){if(saved.containsKey(e.getPlayer().getUniqueId()))e.setCancelled(true);}
 @EventHandler public void pickup(org.bukkit.event.entity.EntityPickupItemEvent e){if(e.getEntity() instanceof Player p&&saved.containsKey(p.getUniqueId()))e.setCancelled(true);}
 @EventHandler public void command(PlayerCommandPreprocessEvent e){if(saved.containsKey(e.getPlayer().getUniqueId())){e.setCancelled(true);e.getPlayer().sendMessage("§cComandos bloqueados durante a luta.");}}
 @EventHandler public void teleport(PlayerTeleportEvent e){if(saved.containsKey(e.getPlayer().getUniqueId())&&e.getCause()!=PlayerTeleportEvent.TeleportCause.PLUGIN)e.setCancelled(true);}
 private void persist(){for(var e:saved.entrySet())getConfig().set("recovery."+e.getKey(),e.getValue().encode());if(getConfig().isConfigurationSection("recovery"))for(String k:new HashSet<>(getConfig().getConfigurationSection("recovery").getKeys(false)))if(!saved.containsKey(UUID.fromString(k)))getConfig().set("recovery."+k,null);saveConfig();}
 private void recover(){if(!getConfig().isConfigurationSection("recovery"))return;for(String k:getConfig().getConfigurationSection("recovery").getKeys(false))try{saved.put(UUID.fromString(k),State.decode(getConfig().getString("recovery."+k)));}catch(Exception ex){getLogger().severe("Falha ao recuperar dados de "+k);}}
 public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){return c.getName().equalsIgnoreCase("x1")&&args.length==1?List.of("aceitar","recusar","cancelar"):Collections.emptyList();}
 private static class State implements Serializable{private static final long serialVersionUID=1L;String world;double x,y,z,hp;float yaw,pitch,exp,sat;int food,level,fire;GameMode mode;ItemStack[] contents,armor;ItemStack off;
 static State take(Player p){State s=new State();Location l=p.getLocation();s.world=l.getWorld().getName();s.x=l.getX();s.y=l.getY();s.z=l.getZ();s.yaw=l.getYaw();s.pitch=l.getPitch();s.contents=p.getInventory().getStorageContents();s.armor=p.getInventory().getArmorContents();s.off=p.getInventory().getItemInOffHand();s.hp=p.getHealth();s.food=p.getFoodLevel();s.sat=p.getSaturation();s.exp=p.getExp();s.level=p.getLevel();s.fire=p.getFireTicks();s.mode=p.getGameMode();return s;}
 void putBack(Player p){World w=Bukkit.getWorld(world);if(w!=null)p.teleport(new Location(w,x,y,z,yaw,pitch));p.getInventory().clear();p.getInventory().setStorageContents(contents);p.getInventory().setArmorContents(armor);p.getInventory().setItemInOffHand(off);p.setGameMode(mode);p.setFoodLevel(food);p.setSaturation(sat);p.setExp(exp);p.setLevel(level);p.setFireTicks(fire);p.setHealth(Math.max(1,Math.min(hp,p.getAttribute(Attribute.MAX_HEALTH).getValue())));}
 String encode(){try{ByteArrayOutputStream b=new ByteArrayOutputStream();BukkitObjectOutputStream o=new BukkitObjectOutputStream(b);o.writeObject(this);o.close();return Base64.getEncoder().encodeToString(b.toByteArray());}catch(Exception e){throw new IllegalStateException(e);}}
 static State decode(String v)throws Exception{BukkitObjectInputStream i=new BukkitObjectInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(v)));State s=(State)i.readObject();i.close();return s;}}
}